  "新建规则草稿 · 基于": "New rule draft · based on",
  "新建规则向导": "New rule wizard",
  "发布规则版本": "Publish rule version",
  "确认发布": "Confirm publish",
  "留空表示立即生效；填未来时点即安排生效，到点后自动按新版本报价。生效时点必须晚于已发布的最新版本。": "Leave blank to take effect immediately. A future time schedules activation; it must be later than the latest published version.",
  "发布原因": "Publish reason",
  "发布原因必填并写入审计": "A publish reason is required and recorded in the audit.",
  "当前生效版本": "Active version",
  "无（首次发布）": "None (first release)",
  "生效后被替代": "Superseded after activation",
  "已锁定报价": "Locked quotes",
  "张，仍按各自规则快照结算，不受本次发布影响": " quotes; each remains settled from its rule snapshot.",
  "恢复规则版本": "Restore rule version",
  "生成新草稿": "Create new draft",
  "恢复只会按该版本的内容生成新草稿": "Restore creates a new draft from this version only.",
  "被恢复的版本原样保留，已发布版本不可修改；新草稿仍需具备发布权限的人发布后才对客户生效。": "The restored version is preserved and published versions cannot be edited; an authorized user must publish the new draft.",
  "恢复原因必填并写入审计": "A restore reason is required and recorded in the audit.",
  "作废规则版本": "Void rule version",
  "确认作废": "Confirm void",
  "作废后该版本不再参与任何租期的规则匹配": "After voiding, this version will no longer match any rental period.",
  "若它是当前唯一生效版本，作废后落在该时段的报价会直接失败而不是回落到旧规则；请先发布替代版本。已锁定的报价与订单按各自快照结算，不受影响。": "If it is the only effective version, quotes in its period will fail after voiding instead of falling back. Publish a replacement first; locked quotes and orders are unaffected.",
  "作废原因必填并写入审计": "A void reason is required and recorded in the audit.",
  "留空表示不按边界计费": "Leave blank to avoid boundary-based billing.",
  "按连续 24 小时分段，不按午夜切日。使用同一定价分组、同一价格版本的 24 小时日价；未配置日价不能使用。发布后随新订单规则固定，不改变已有订单。": "Bill in consecutive 24-hour segments rather than midnight calendar days. Use the 24-hour price from the same rate group and version; a configured day price is required. Published rules are fixed into new orders.",
  "选择本空间的续租计费方式": "Choose this workspace's extension billing method",
  "单独计费保留原租期金额，新增时段按申请时价格计算；完整重算沿用原价格与原优惠，再扣此前已计金额。两种方式都检查后续占用及缓冲。发布后新订单固定所选方式，改设置不影响旧订单。": "Incremental billing preserves the original term amount and prices the added time at request time. Full recalculation reuses the original price and discount, then subtracts amounts already charged. Both check future reservations and buffers.",
  "新增时段单独计费（原方式）": "Bill the added period separately (original)",
  "不退租金": "No rental refund",
  "按规则自动退": "Refund automatically by rule",
  "人工审批后退": "Refund after manual review",
  "标价即含税，客户看到的应付金额不变": "Listed prices include tax; the payable amount is unchanged",
  "税额由含税额反算（含税额 × 税率 ÷ (1 + 税率)），只进报表与开票，不改变报价与订单的应付金额。押金不计税。香港等无增值税的空间填 0 即可。": "Tax is reverse-calculated from the tax-inclusive amount and appears only in reports and invoices. It does not change quote or order payable amounts; deposits are not taxed.",
  "例如：增值税 13%": "Example: VAT 13%",
  "年": "year",
  "月": "month",
  "上一月": "Previous month",
  "下一月": "Next month",
