  "停止": "Closed",
  "自助": "Self-service",
  "角标「覆盖」表示该日期存在人工覆盖，点击日期查看基础值、生效值与覆盖详情。": "The Override badge means a manual override exists. Click the date to view base, effective, and override details.",
  "一次性特殊价格由价格模块提供": "One-off special prices are provided by the pricing module",
  "价格值由价格计划维护；日历范围覆盖只保存一次性价格规则的稳定引用，不保存商品价格或空间统一系数。": "Price values are maintained by pricing plans. Calendar range overrides store only a stable reference to a one-off rule, not item prices or workspace-wide coefficients.",
  "请选择日期范围": "Select a date range",
  "日期时间范围必须同时提供开始与结束时点": "Provide both the start and end of the date-time range",
  "至少选择并填写一个要设置的字段": "Select and fill at least one field to set",
