  "从原起租时间算到新归还时间，沿用原价格版本和原优惠规则，扣除此前已计金额；零差额无需补款，负差额另走退款审核。": "Recalculate from the original start time to the new return time using the original price version and discount rules, then deduct the amount already charged. No payment is due for zero difference; a negative difference requires refund review.",
