  "确认换货": "Confirm exchange",
  "仅支持租赁中的整行换货；新商品会立即锁定。原商品可返回仓库释放库存，或下架隔离。金额按所选价格依据重算，差额统一进入订单结算。": "Only full-line exchanges for active rentals are supported. The replacement is reserved immediately. Return the original item to inventory or take it off shelf; amounts are recalculated using the selected price basis and settled with the order.",
