  "试算差额": "Preview difference",
  "确认并应用": "Confirm and apply",
  "仅支持取货前部分取消": "Partial cancellation is available before pickup only.",
  "数量库存和一次性耗材可以按数量取消；序列化资产只能整行取消。未开始的可选增值服务可以单独取消，退款按订单快照中的客户净支付计算并释放服务容量。原订单与原报价不会被覆盖；商品与服务取消不能在同一次变更中混合。": "Quantity stock and consumables can be cancelled by quantity; serialized assets can only be cancelled as a whole line. Unstarted optional services can be cancelled separately. Refunds use the customer's net payment in the order snapshot and release service capacity. The original order and quote are retained; product and service cancellations cannot be mixed in one change.",
  "请选择商品取消项或未开始的增值服务，且两者只能选一种": "Select either product cancellation or an unstarted add-on, not both",
