  "最终时限已到。确认后会释放库存、服务容量和优惠券占用；已支付金额按规则进入待退款/资金处理。": "The final deadline has passed. Confirmation releases inventory, service capacity, and coupon reservations; paid amounts enter the refund / funding process according to the rules.",
  "这是有权限人员的提前确认。请确认已通知客户并填写事实原因；确认后会释放库存、服务容量和优惠券占用。": "This is an early confirmation by an authorized user. Confirm that the customer was notified and record the factual reason; confirmation releases inventory, service capacity, and coupon reservations.",
