  "正数客户费用须有客户责任依据；正常损耗和责任未明不能收费。请在审核理由中记录证据与合同依据。": "A positive customer charge requires established customer liability. Do not charge for normal wear or unresolved liability. Record evidence and contractual grounds in the review reason.",
