  "按事故证据填写，不要以检查或审核时间代替。": "Use incident evidence, not the inspection or review time.",
  "指定冻结免赔发生项": "Select frozen waiver occurrence",
  "可留空按可适用保障比较；不叠加不同发生项的额度。": "Leave blank to compare eligible coverage; limits from separate occurrences are not combined.",
  "请核对冻结条款、异常商品与责任范围，并在审核理由中说明依据。费用填写免赔计算前的裁定金额。": "Check the frozen terms, affected item and liability, and explain your decision. Enter the assessed charge before applying the waiver.",
  "符合免赔条款，按快照计算减免": "Covered by the terms; apply the frozen waiver",
  "不适用免赔，按裁定金额计费": "Not covered; charge the assessed amount",
  "记录客户确认 / 申诉": "Record customer confirmation / dispute",
  "当前已有客户申诉；只有再次明确记录客户确认后，订单才可以继续结算。": "The customer has disputed this already. The order can continue to settlement only after a new explicit customer confirmation is recorded.",
  "审核通过的异常费用必须有客户确认或申诉记录；申诉会继续阻断结算，不会被当作已处理。": "An approved exception charge requires a customer confirmation or dispute record. A dispute continues to block settlement and is not treated as resolved.",
