  "服务履约": "Service fulfillment",
  "实际时间由本次操作记录，计划时段不能自动证明服务已经履约。": "Actual times are recorded by this operation; a scheduled window does not prove fulfillment.",
  "完成服务必须填写执行结果，并明确记录客户是否确认；数量服务可以分次记录，未执行部分仍会保持待处理。": "Completing a service requires an execution result and an explicit customer confirmation. Quantity-based services can be recorded in parts; the remainder stays pending.",
  "取消、失败或未到场会按未执行部分的净额生成待审核退款；批准后仍需到资金区办理实际退款。": "Cancellation, failure, or no-show creates a refund review for the unexecuted net amount. After approval, process the actual refund in the funding section.",
  "点击确认后记录当前时间为实际开始时间。": "Confirm to record the current time as the actual start time.",
