  "规则建议金额": "Rule-suggested amount",
  "批准只表示退款/释放已获认可，本单不动账；押金、预授权与多收租金的实际退款/释放要到资金区由具备资金权限的人员办理。": "Approval only recognizes the refund or release; this order's ledger is not changed. Actual deposit, preauthorization, and overpayment refunds or releases must be handled in the funding section by authorized staff.",
  "批准后只核减应收并生成待退款；实际退款要到资金区由具备资金权限的人员办理。": "Approval only reduces the receivable and creates a pending refund; the actual refund must be handled in the funding section by authorized staff.",
  "批准后按认定额计入应收；实际收款要到资金区单独登记。": "Approval adds the decided amount to the receivable; actual collection must be recorded separately in the funding section.",
