  "官网首页每个一级品类卡片/场景图的展示图。建议 800×600px（4:3），≤ 500KB，JPG/WebP；留空则自动使用该品类下第一个商品的图片。品类来自“通用客户端配置”里已启用的经营空间。": "Images shown on top-level category cards or scenes on the website home page. Recommended: 800×600 px (4:3), up to 500 KB, JPG/WebP. When empty, the first product image in the category is used. Categories come from enabled workspaces published in “Shared client configuration”.",
