  "浏览器图标": "Browser icon",
  "留空使用系统默认蓝 #1677FF；设置后客户端与管理后台主色跟随": "Empty uses the system blue #1677FF; clients and the admin console follow this color when set.",
  "留空则按空间默认标记选择；必须在已发布服务之内": "Empty selects the workspace marked as default; it must be one of the published services.",
