  "留空则使用通用文案。图标关键字可填 authentic / delivery / flexible / service / quality / support，其余用默认勾选图标。": "Empty uses shared copy. Icon keywords can be authentic / delivery / flexible / service / quality / support; other values use the default check icon.",
  "留空则首页不展示评价区块。请如实使用已获授权的客户评价。": "When empty, the home page hides the testimonial section. Use customer testimonials only with permission.",
