  "未选择的明细保持不变。可在下单时定价组范围内切换型号，每条预留选择一种型号；库存预留同步转移，订单价格不变。跨型号或更换已锁定资源需改配权限与原因。": "Unselected lines remain unchanged. Models can be switched within the rate group during ordering, with one model per reservation. Inventory reservations move with the selection and the order price does not change. Switching models or replacing locked resources requires reassignment permission and a reason.",
