  "下载内容是客户可读 HTML 快照，不包含内部风控、成本、权限或敏感证件信息；法定发票、正式 PDF 和电子签章另行处理。": "The download is a customer-readable HTML snapshot and contains no internal risk, cost, permission, or sensitive identity-document data. Statutory invoices, formal PDFs, and electronic signatures are handled separately.",
