  "默认服务": "Default service",
  "配置小程序、APP 与 web 官网对客户展示的品牌、客服、协议、帮助与发布服务（租户级共用），以及微信小程序凭证与官网特有内容。": "Configure the tenant-wide brand, support, policies, help, and published services shown to customers in the mini program, app, and web site, plus WeChat mini program credentials and website-specific content.",
  "品类入口图": "Category entry images",
  "品牌、客服、协议正文/版本、帮助与发布服务由小程序、APP 和官网共用；微信 AppID/AppSecret 是微信渠道专有；站点标语、Hero、辅助色、页脚与 SEO 是官网专有。协议正文在客户端内直接渲染，请填写正文而不仅是外链。": "Brand, support, policy content and versions, help, and published services are shared by the mini program, app, and website. WeChat AppID/AppSecret are specific to WeChat. Site slogan, Hero, accent color, footer, and SEO are website-specific. Policy content is rendered in the client, so provide the content rather than only an external link.",
