  "注册策略、注册审核与资质资料在租户内共享；切换经营空间仍显示同一份会员及审核记录。来源空间仅用于追溯，不限制审核结果的共享范围。会员暂停、退出或注销影响租户全部空间；证件类型及下单要求仍由各空间配置。": "Registration policy, registration reviews, and qualification records are shared within the tenant. Switching workspaces still shows the same members and review records. The source workspace is for traceability only and does not limit review sharing. Suspending, leaving, or closing a member affects all tenant workspaces; document types and order requirements remain workspace-specific.",
