  "注册、实名审核和首单完成会自动触发奖励判断": "Registration, identity verification, and first-order completion automatically trigger reward evaluation",
  "下方人工入口只用于补偿与联调；自动事件使用客户事件幂等键。积分、营销余额和奖励券会进入 Rental Core 权益账户；营销余额不是支付机构资金账户。奖励触发规则在「品类与业务规则 → 会员奖励规则」维护。": "The manual entry below is for compensation and integration testing only. Automatic events use customer-event idempotency keys. Points, marketing balance, and reward coupons are recorded in Rental Core benefit accounts; marketing balance is not a payment-provider account. Maintain reward triggers under Category & business rules → Membership reward rules.",
