  "新增方案": "Add plan",
  "会员方案在租户内共享，切换经营空间仍显示同一份方案。每条权益可适用于全部空间、指定空间或指定品类；已发布版本不可回写，已授予的权益以快照为准。会员暂停、退出或注销影响租户全部空间。": "Membership plans are shared within the tenant. Switching workspaces shows the same plans. Each benefit can apply to all workspaces, selected workspaces, or selected categories. Published versions cannot be rewritten; granted benefits use snapshots. Suspending, leaving, or closing a member affects all tenant workspaces.",
