  "租户统一会员：企业主档、管理员与员工关系共享。": "Tenant-wide membership: corporate profiles, administrators, and employee relationships are shared.",
  "新增企业会员": "Add company member",
  "企业主档、管理员及员工关系在租户内共享，切换经营空间仍显示同一份名单。管理员和员工必须是租户内的有效个人会员；会员暂停、退出或注销影响租户全部空间。企业权益还需符合每条权益的适用范围。": "Corporate profiles, administrators, and employee relationships are shared within the tenant. Switching workspaces shows the same list. Administrators and employees must be active personal members in the tenant; member suspension, exit, or closure affects all workspaces. Corporate benefits must also satisfy each benefit's scope.",
