  "支付宝网页、手机网页或二维码收款。私钥只在服务端加密保存。": "Alipay web, mobile web, or QR-code payments. The private key is encrypted and stored only on the server.",
  "微信 JSAPI、APP、Native 或 H5 收款。回调必须经过 API v3 验签。": "WeChat JSAPI, app, Native, or H5 payments. Callbacks must pass API v3 signature verification.",
  "对象存储直传。客户端只拿短时上传授权，不暴露长期 AccessKey。": "Direct object-storage uploads. Clients receive short-lived upload authorization; long-lived AccessKeys are never exposed.",
  "对象存储直传。客户端只拿短时上传授权，不暴露长期 SecretKey。": "Direct object-storage uploads. Clients receive short-lived upload authorization; long-lived SecretKeys are never exposed.",
  "兼容 S3 签名的对象存储服务。适合已有私有云或其他云厂商。": "Object storage compatible with S3 signing, suitable for private clouds or other cloud providers.",
  "地域": "Region",
