  "可选；微信退款结果通知地址。未配置时继续通过退款查询恢复，不把受理当成成功。": "Optional. WeChat refund result notification URL. Without it, refund queries continue to reconcile results; acceptance is not treated as success.",
  "平台证书序列号": "Platform certificate serial number",
  "用于匹配微信回调请求头中的 Wechatpay-Serial，不是商户证书序列号。": "Used to match Wechatpay-Serial in callback headers; this is not the merchant certificate serial number.",
