  "对象前缀": "Object prefix",
  "使用 Path Style": "Use Path Style",
  "部分兼容 S3 的私有对象存储需要使用路径式地址；云厂商默认不需要。": "Some private S3-compatible stores require path-style URLs; cloud providers usually do not.",
  "启用此平台": "Enable provider",
  "允许系统调用这个平台；保存后还需要通过“测试连接”才能真正用于业务。": "Allow the system to call this platform. After saving, it must pass Connection test before it can be used in business operations.",
  "关闭后保留配置，但业务不会调用。": "The configuration is retained when disabled, but business operations will not call it.",
  "设为该能力默认平台": "Set as the default platform for this capability",
  "同一种能力可以配置多个平台，但实际支付、短信或文件调用只使用默认平台。": "Multiple platforms can be configured for one capability, but payment, SMS, or file calls use only the default platform.",
  "同一能力只能有一个默认平台。": "Only one default platform is allowed for each capability.",
  "请输入": "Enter ",
  "暂时无法读取租户第三方服务配置，请刷新重试。": "Tenant third-party service configuration is temporarily unavailable. Refresh and try again.",
  "为当前租户选择并配置支付、短信和云存储平台。配置按租户共享给各经营空间，业务模块只使用统一适配器。": "Select and configure payment, SMS, and cloud-storage platforms for the current tenant. Configuration is shared with all workspaces in the tenant, and business modules use a unified adapter.",
  "密钥只在服务端加密保存": "Secrets are encrypted and stored only on the server",
  "页面不会回显 AccessKey、私钥、API 密钥等敏感值；停用平台不会删除配置，重新启用时可继续使用。“测试连接”只发起无副作用探针：支付查询随机交易号、短信查询模板、云存储 HEAD 随机不存在对象，不会扣款、发短信或写入文件。": "The page never reveals AccessKeys, private keys, API keys, or other sensitive values. Disabling a platform does not delete its configuration. Connection test performs only harmless probes: payment lookup of a random transaction, SMS template lookup, or a HEAD request for a random missing object. It does not charge, send SMS, or write files.",
  "一个能力可以配置多个平台": "One capability can use multiple platforms",
  "支付可以同时启用支付宝和微信支付；短信、云存储也可以分别配置多个平台，并指定默认平台。保存某个平台时不会覆盖其他平台。": "Alipay and WeChat Pay can be enabled together. SMS and cloud storage can also have multiple platforms with a default selected. Saving one platform does not overwrite the others.",
