  "租户管理": "Tenant management",
  "一个租户可有多个经营空间；已有空间的品类固定，新增品类请新建空间。租户不做物理删除。": "A tenant can have multiple workspaces. A workspace's category is fixed after creation; create a new workspace for another category. Tenants are never physically deleted.",
