  "初始化将原子创建租户档案、首个默认经营空间、根组织、租户管理员、默认角色、字典和编号规则。后续可继续新增其他品类空间。模板项：": "Initialization atomically creates the tenant profile, first default workspace, root organization, tenant administrator, default roles, dictionaries, and numbering rules. More category workspaces can be added later. Templates:",
  "类。": " types.",
  "冻结或停用会立即撤销该租户所有登录会话；恢复为正常后账号可重新登录。": "Freezing or disabling immediately revokes all tenant login sessions. Accounts can sign in again after the tenant returns to normal.",
  "新增经营空间": "Add workspace",
