  "地点名称取下单时快照；主档改名不改写历史订单，因此这里显示的是该地点订单最多的那个名称。逐行订单量与金额相加等于上方总量，可与订单明细对账。": "Location names come from the booking snapshot and are not rewritten when the master record changes. Row totals reconcile to the totals above and can be checked against order details.",
  "地点维度": "By location",
  "订单、收入、优惠、异常、库存与地点客户口径。指标定义四个品类一致，仅标题使用品类术语。": "Orders, revenue, discounts, exceptions, inventory, and location/customer metrics for the current workspace. Metric definitions are consistent across four categories; only the title uses category terminology.",
  "订单量": "Order count",
  "订单量按状态": "Orders by status",
  "订单量为非草稿订单数；租赁收入只含租金；优惠金额为方案优惠与券优惠合计；应收金额为调账后应收，税为价内税——「不含税应收」与「其中税额」是它的拆分，不要相加；异常费用取订单费用行中的逾期、损坏与取消。仅统计当前经营空间，不做跨空间汇总；导出与本页使用同一份数据与筛选。": "Order count excludes drafts. Rental revenue includes rent only. Discounts combine plan and coupon discounts. Receivables are after adjustments and include in-price tax; before-tax receivables and tax are components and must not be added together. Exceptions include overdue, damage, and cancellation fees. Only the current workspace is included; exports use the same data and filters.",
