  "自营机构与合作商是经营主体；门店、仓库、自提柜、取还点和项目现场是主体下的履约地点。订单保存地点与经营主体快照，避免后续档案变更影响历史单据。": "Self-operated organizations and partners are operating entities. Stores, warehouses, lockers, pickup/return points, and project sites are fulfillment locations under them. Orders save location and entity snapshots so later profile changes do not alter historical documents.",
  "取还点": "Pickup / return point",
  "自提柜": "Locker",
  "配送中心": "Delivery hub",
  "项目现场": "Project site",
  "仓储": "Storage",
  "配送": "Delivery",
  "请将以下临时密码安全交给账号持有人，首次登录必须修改。": "Safely provide the temporary password below to the account holder. It must be changed at first sign-in.",
  "运营账号与空间权限已保存": "Staff account and workspace permissions saved",
  "保存失败，请检查基础角色、空间角色和账号唯一性": "Could not save. Check the base role, workspace roles, and account uniqueness.",
  "账号状态已更新": "Account status updated",
  "账号状态更新失败": "Could not update account status",
  "密码已重置": "Password reset",
  "密码重置失败": "Could not reset password",
  "运营账号管理": "Staff accounts",
  "账号属于租户；可访问空间、空间角色和数据范围按每个经营空间分别授权。": "Accounts belong to a tenant. Workspace access, workspace roles, and data scopes are authorized separately for each workspace.",
  "权限分为两层": "Permissions have two layers",
  "角色决定可以执行哪些操作；数据范围决定在获准操作内可以看哪些数据。经营空间访问权单独授予，不能只靠隐藏菜单代替。": "Roles determine which actions can be performed. Data scopes determine which data can be viewed within those actions. Workspace access is granted separately; hiding menus is not a substitute.",
  "个运营账号": "staff accounts",
  "新增运营账号": "Add staff account",
  "手机": "Phone",
  "归属组织": "Organization",
  "已关联组织": "Organization assigned",
  "组织范围账号只能访问当前组织及下级组织明确关联的履约地点；未关联地点不会自动归属。": "Accounts with organization scope can access only fulfillment locations explicitly assigned to their organization or an enabled descendant. Unassigned locations are not inherited.",
  "租户基础角色": "Tenant base role",
  "可访问空间": "Accessible workspaces",
