  "经营空间授权": "Workspace access",
  "启用空间后必须指定该空间的角色；数据范围可覆盖角色默认值。关闭空间会使该账号无法进入该空间。": "An enabled workspace must have a role. The data scope can override the role default. Disabling a workspace prevents this account from entering it.",
  "允许访问": "Access allowed",
  "空间角色（操作权限）": "Workspace role",
  "数据范围": "Data scope",
  "员工履约地点范围": "Staff location access",
  "全部履约地点": "All locations",
  "仅指定地点": "Selected locations",
  "选择至少一个地点": "Select at least one location",
  "角色权限管理": "Roles & permissions",
  "RBAC 角色统一管理操作权限；数据范围单独设置，并可在账号的具体经营空间授权中覆盖。": "RBAC roles manage action permissions centrally. Data scopes are configured separately and can be overridden in an account's workspace access.",
  "操作权限": "Action permissions",
  "决定账号能进入哪些页面、查看哪些模块，以及可以执行新增、编辑、审核、发布等动作。": "Determines which pages and modules an account can access and whether it can add, edit, review, publish, and perform other actions.",
  "数据权限": "Data permissions",
  "决定操作获准后可访问的数据边界。当前空间隔离已强制生效；组织/本人范围仍需各业务模块逐项接入。": "Determines the data boundary after an action is allowed. Workspace isolation is enforced; organization and own-data scopes still require individual module integration.",
  "角色可复用于多个运营账号和经营空间": "Roles can be reused across staff accounts and workspaces",
