  "租户级": "Tenant",
  "业务组织": "Business organization",
  "履约点": "Fulfillment point",
  "模型": "Model",
  "品类与租赁方式": "Category & rental options",
  "计价方式": "Pricing",
  "订单、报价与本空间所有配置金额的币种。开通租户时设定，此处不可修改。": "Currency for orders, quotes, and all configured amounts in this workspace. It is set when the tenant is opened and cannot be changed here.",
  "启用计价单位": "Billing units",
  "默认单位": "Default unit",
  "启用旧版周末/节假日倍率": "Enable legacy weekend / holiday multipliers",
  "兼容开关，只作用于价格里的旧字段「周末系数」「节假日系数」。关闭后这两个系数不再参与计价，落回商品基础价；逐商品配置的日期类型价格、周期性计价时段与一次性日期时间覆盖不受影响，照常生效。": "Compatibility switch for the legacy price fields “weekend multiplier” and “holiday multiplier”. When disabled, these multipliers are ignored and pricing falls back to the item base price. Per-item day-type prices, recurring time windows, and one-time date/time overrides continue to apply.",
  "收款方式": "Payment methods",
  "启用收款方式": "Enabled payment methods",
  "线下现金和线下转账可直接登记；支付宝、微信还必须在租户集成设置中完成账号配置、启用并通过实时校验后，客户端才会展示为可用。": "Offline cash and bank transfer can be recorded directly. Alipay and WeChat Pay appear to clients only after the tenant integration is configured, enabled, and passes a live check.",
  "支付时点、押金与预授权、异地归还、逾期计费在「业务规则」页配置，发布后随订单快照冻结。": "Configure payment timing, deposits and preauthorizations, cross-location returns, and overdue billing on the Business rules tab. Published settings are frozen in the order snapshot.",
  "租赁与履约方式": "Rental & fulfillment",
  "自动预分配资源": "Auto-allocate stock",
  "提前预分配（天）": "Allocate ahead (days)",
  "到时自动锁定分配": "Auto-lock allocation",
  "领取前锁定（分钟）": "Lock before pickup (min)",
  "保护人工分配结果": "Keep manual allocations",
  "自动任务每分钟检查一次；不自动换掉锁定资源，不跨地点调拨，失败转待人工处理。": "The automatic job checks every minute. It does not replace locked resources or move resources between locations; failures are sent for manual handling.",
  "启用方式": "Available fulfillment methods",
  "保存租户设置": "Save tenant settings",
  "保存租户设置失败，请检查填写内容": "Could not save tenant settings. Check the entered values.",
  "租户经营设置已保存": "Tenant operating settings saved",
  "业务规则": "Business rules",
  "营业日历": "Business calendar",
  "会员奖励规则": "Member rewards",
  "通知模板": "Notification templates",
  "租户经营品类决定允许范围；价格、日历、规则、奖励与通知均按版本留痕。": "The tenant's business category determines the allowed scope. Prices, calendars, rules, rewards, and notifications are versioned.",
  "经营品类创建后固定；租户只能在品类支持的计价、履约、库存、预授权和资质能力内配置。": "The business category is fixed after creation. The tenant can configure only pricing, fulfillment, inventory, preauthorization, and qualification capabilities supported by that category.",
  "这里只配置奖励规则；人工补发、客户权益账户与奖励流水在「会员与客户 → 会员激励」页维护。积分、营销余额和奖励券会进入 Rental Core 权益账户；营销余额不是支付机构资金账户。": "Configure reward rules here. Manual grants, customer benefit accounts, and reward ledgers are managed under Members & Customers → Member rewards. Points, marketing balance, and reward coupons go into Rental Core benefit accounts; marketing balance is not a payment-provider account.",
  "奖励类型": "Reward type",
  "赠送券模板（奖励类型为优惠券时必选）": "Coupon template (required when the reward type is coupon)",
  "邀请奖励": "Referral reward",
