  "导入当前经营空间的支付平台对账文件，核对差异并保留人工处理记录。": "Import payment-provider statements for the current workspace, review differences, and retain manual handling records.",
  "对账只产生证据，不会自动改写支付或退款事实": "Reconciliation only creates evidence; it never rewrites payment or refund facts automatically",
  "重复导入同一经营空间、平台和文件会直接返回原批次。金额、币种、状态、第三方流水号或本地记录不一致时，必须由授权人员逐条确认或标记待向平台核对。": "Re-importing the same file for the same workspace and provider returns the original batch. Differences in amount, currency, status, third-party reference, or local records must be reviewed by an authorized operator or marked for provider verification.",
