  "导入并核对": "Import and reconcile",
  "单个文件不超过 10MB、最多 10,000 行；文件应包含 kind、status、amount、currency 和商户订单号列，退款行还需商户退款单号。": "Each file must be no larger than 10 MB and contain at most 10,000 rows. It must include kind, status, amount, currency, and merchant order number columns; refund rows also require a merchant refund number.",
