  "调用失败，请检查 JSON 与适配器参数": "Call failed. Check the JSON and adapter parameters.",
  "二次确认检查失败": "Second-confirmation check failed",
  "立即执行任务": "Run task now",
  "该操作会写入异步任务执行结果。当前内置任务为 mock/本地能力，接入真实外部系统前需重新评估影响。": "This writes the asynchronous job result. The built-in job is a mock/local capability; reassess its impact before connecting a real external system.",
  "执行任务": "Run task",
  "提供方": "Provider",
  "公共官方日历来源": "Official calendar sources",
  "登记中国大陆官方节假日来源与年度来源版本。租户经营空间只能引用某一版生成自己的年度草稿并自行确认发布。": "Register official mainland China holiday sources and yearly source versions. Tenant workspaces can only use a version to generate their own draft and publish it after confirmation.",
  "官方数据是公共基础来源，导入不会自动影响任何经营空间": "Official data is a shared foundation source; importing it does not automatically affect any workspace",
  "官方再次调整时请登记新的来源版本；已发布的空间日历、有效报价和订单继续指向它们各自引用的那一版，不会被静默覆盖。": "When the official calendar changes, register a new source version. Published workspace calendars, valid quotes, and orders continue to point to their referenced versions and are never silently overwritten.",
  "登记来源": "Register source",
  "该来源尚未登记任何年度版本": "No yearly version has been registered for this source",
  "年度": "Year",
  "来源版本": "Source version",
  "官方发布日期": "Official publication date",
  "日期条数": "Date count",
  "入库时间": "Imported at",
  "登记人": "Registered by",
  "地区": "Region",
  "来源名称": "Source name",
  "公告地址": "Announcement URL",
  "编辑来源": "Edit source",
  "登记年度版本": "Add annual version",
  "登记官方来源": "Add official source",
  "例如：国务院办公厅年度放假通知": "e.g. State Council General Office annual holiday notice",
  "必须是 HTTPS 地址：这份数据会被所有租户引用，来源不可验证时出错面是全平台。": "Must be an HTTPS URL. All tenants use this data, so an unverifiable source affects the whole platform.",
  "来源版本只追加，版本号由服务端递增": "Source versions are append-only and version numbers are incremented by the server",
  "官方再次调整时请再登记一版，不要修改历史版本——已引用旧版的空间日历、报价与订单必须继续指向原版本。": "Register another version when the official calendar changes. Do not edit historical versions; workspace calendars, quotes, and orders that reference an older version must continue to point to it.",
  "官方公告发布日期": "Announcement date",
  "官方日期（JSON 数组）": "Official dates (JSON array)",
  "只接受法定节假日与调休工作日，日期必须是该年度的 YYYY-MM-DD。整年替换语义：空间应用该版本时，本版未包含的日期会回落到每周模板。": "Only statutory holidays and makeup workdays are accepted. Dates must use YYYY-MM-DD for the selected year. Applying a version replaces the year; dates not included fall back to the weekly template.",
  "官方来源已保存": "Official source saved",
  "已登记来源版本": "Source version registered",
  "租户空间可以引用它生成草稿": "Tenant workspaces can reference it to generate a draft",
  "登记失败：请检查年度、发布日期与日期数组": "Registration failed. Check the year, publication date, and date array",
  "登记": "Register",
  "YYYY-MM-DD": "YYYY-MM-DD",
  "YYYY-MM-DD HH:mm": "YYYY-MM-DD HH:mm",
  "按业务顺序逐段配置这套租赁规则，每步只需关注当前一组。可随时「保存草稿」中途退出，最后一步发布后立即对客户生效。": "Configure the rental rules in business order, focusing on one group at a time. You can save a draft and exit; the rules take effect for customers after the final step is published.",
  "计价基础": "Pricing basics",
  "决定按什么时间单位计费。": "Determines which time units are billable.",
  "领取与归还": "Pickup & return",
  "领取和归还时的检查与缓冲要求。": "Inspection and buffer requirements for pickup and return.",
  "收款与押金": "Payments & deposits",
  "何时收款、押金与预授权怎么算。": "When to collect payment and how to calculate deposits and preauthorizations.",
  "取消、爽约与逾期": "Cancellations, no-shows & lateness",
  "客户提前取消、过期未取、逾期归还时如何计费；金额按下单时的规则版本冻结。": "How to charge for early cancellation, expired pickup, and overdue return. Amounts are frozen to the rule version at booking time.",
  "续租与提前归还": "Extensions & early returns",
  "允许续租/提前归还时的计费。": "Charges when extension or early return is allowed.",
  "损坏与资质": "Damage & eligibility",
  "损坏定责与下单前的资质门槛。": "Damage responsibility and qualification requirements before booking.",
