  "配置可以先保存，但支付下单、短信发送和文件上传等新业务调用会被服务端拒绝。请先补齐配置并点击“测试连接”，测试通过后才会进入真实运行链。": "Configuration can be saved first, but new business calls such as payments, SMS, and file uploads will be rejected by the server. Complete the configuration and click “Test connection”; only then will the integration enter live operation.",
