  "重置后会生成临时密码，请通过安全渠道交付给账号持有人，并要求首次登录后修改。": "A temporary password will be generated. Deliver it to the account holder through a secure channel and require a change after the first login.",
  "预设角色或仍分配给账号的角色无法删除。删除操作不可撤销。": "Preset roles or roles still assigned to accounts cannot be deleted. Deletion cannot be undone.",
