  "管理后台圆角（分组）": "Corner radius",
  "容器、按钮、录入控件各自独立调节；圆形图标按钮、开关与胶囊标签保留各自形态不受影响。容器与输入为 8–40px（可做大圆角卡片），仅按钮组可选最右的 999px 极致圆角（胶囊按钮）；留空的组回退到旧的统一圆角。": "Set separate radii for containers, buttons and inputs. Circular icon buttons, switches and pill badges keep their shape. Containers and inputs support 8–40px; only buttons support the 999px pill option. Blank groups inherit the legacy shared radius.",
  "容器圆角": "Container radius",
