  "资金费率保存失败，请检查规则与待生效调价": "Could not save rates. Check the rules and scheduled price changes.",
  "当前价格版本没有该定价组的费率，请先建立或发布基本价": "No rates for this group in the current version. Create or publish base rates first.",
  "当前已发布或草稿规则没有按计价单位收取押金/预授权，无需配置此处费率": "Neither the published rules nor the draft charges deposits or preauthorizations by billing unit. No rates are needed here.",
  "搜索定价分组": "Search rate groups",
  "押金与预授权": "Deposit & preauth",
  "按当前已生效的业务规则填写本计价单位需要的资金金额；押金是实收，预授权是冻结额度，两者分别计算。": "Enter amounts per billing unit under the active rules. Deposits are collected; preauthorizations hold funds. They are calculated separately.",
  "当前已生效规则要求填写此金额": "Required by the active rules",
  "金额或倍数必须大于 0": "Amount or multiplier must be greater than 0",
  "按本行实际租金乘以该倍数": "Multiply this line's actual rent by this value",
  "启用对应规则时必须大于 0": "Must be greater than 0 when the rule is enabled",
  "押金/预授权费率": "Deposit & preauth rates",
  "保存并生成新价格版本": "Save as new rate version",
  "只调整本定价组的押金与预授权金额，不改基本租金。保存后会为整个经营空间追加新价格版本，历史版本和既有订单快照保持不变。": "Updates only this group's deposit and preauthorization amounts, not base rent. Saving adds a workspace-wide rate version. Earlier versions and existing order snapshots stay unchanged.",
  "当前业务规则要求填写此金额": "Required by the rental rules",
  "搜索履约地点": "Search locations",
  "开票资料已保存": "Billing details saved",
  "企业合同已保存": "Contract saved",
  "企业会员待审核": "Company review pending",
  "企业必须完成主体资料人工审核后才能添加员工、获得企业权益或用于下单。个人会员自动审核设置不影响企业审核。": "Company details require manual approval before staff can be added, company benefits granted or orders placed. Automatic individual-member approval does not apply.",
  "企业法定名称": "Legal company name",
  "当前已保存": "Saved value",
  "留空保持不变": "Leave blank to keep",
  "该历史企业尚未完成结构化资料迁移，请核对并填写有效代码；仅后台保存原值，列表和审核历史只显示掩码。": "This legacy company needs a valid structured registration code. Verify and enter it. The full value is stored only in the backend; lists and review history show a masked value.",
  "留空保持现有代码": "Leave blank to keep the current code",
