  "承运延误不计客户租金；时间或凭证无法核实则保持库存占用并人工处理。自营配送不属于承运寄送。": "Carrier delays do not add customer rent. If timestamps or evidence cannot be verified, stock stays reserved for manual review. Local delivery is not carrier shipping.",
