  "至少选择一个商品风险等级": "Select at least one risk level",
  "请填写大于0且不超过100的比例": "Enter a percentage greater than 0 and no more than 100",
  "请填写单笔减免金额上限": "Enter the per-order reduction cap",
  "天气/不可抗力免取消费暂未支持": "Weather / force-majeure waivers not supported",
  "当前不提供自动免取消费开关。特殊情况须通过费用人工审核记录依据，不会仅凭天气标记自动减免费用。": "No automatic cancellation-fee waiver is available. Exceptions require a documented manual fee review; a weather flag alone does not waive charges.",
  "损坏费用始终人工核定": "Damage charges require review",
  "损坏及异常费用必须经人工核定并保留审核记录后才能进入应收；首期不支持关闭此保护。": "Damage and exception charges require manual assessment and an audit record before becoming receivables. This safeguard cannot be disabled in this release.",
  "当前品类不支持下单资质审核；证件仍可在会员资料中管理，不作为订单门槛。": "This category does not support pre-booking eligibility checks. Customer documents can still be managed in member profiles but do not block orders.",
  "当前仅支持支付宝和微信支付的 CSV 对账文件；Stripe 文件导入尚未开放。": "Only Alipay and WeChat Pay CSV statements are supported. Stripe imports are not available yet.",
  "本页配置已保存": "Settings saved",
  "已保存功能目录项": "Feature saved",
  "保存失败，请稍后重试（后端服务联调中）": "Could not save. Try again later; backend integration is in progress.",
  "编辑功能目录项": "Edit feature",
  "新增功能目录项": "Add feature",
  "当前归属选「基础版」即把该 PRO 功能公共下放给基础版；修改归属不会把未交付功能改成已上线，也不得静默停用基础版既有承诺。": "Assigning a PRO feature to Basic makes it available to all Basic customers. This does not launch unfinished features or permit silently removing existing Basic commitments.",
  "功能标识": "Feature key",
  "摄影设备": "Camera gear",
  "露营装备": "Camping gear",
  "车辆载具": "Vehicles",
  "默认归属": "Default plan",
  "当前归属（选基础版=公共下放）": "Current plan (Basic = included for all)",
  "上线状态": "Release status",
  "客户价值": "Customer benefit",
  "前提条件": "Requirements",
  "外部费用说明": "External costs",
  "重新加载失败": "Could not reload",
  "已保存办理": "Subscription change saved",
  "线下收款须先核实到账。正式 PRO 销售尚未开放，仅可按明确依据登记受控试点；保存失败不等于退款，请勿要求重复付款。所有时间采用租户统一服务时区，不随空间或浏览器改变。": "Verify receipt before recording an offline payment. PRO sales are not open; only documented, controlled pilots may be recorded. A failed save is not a refund: do not request payment again. All times use the tenant's service time zone, not the workspace or browser zone.",
  "关联待处理申请": "Link pending request",
  "保存实际授权成功后，将同时完成此申请；失败时申请保持待处理。仅登记咨询 / 不续费无需授权操作。可公开办理依据将进入申请记录，请勿填内部敏感信息。": "Saving the actual entitlement also completes this request. If saving fails, it stays pending. Inquiries and non-renewal records do not require entitlement changes. Public notes appear in the request; do not include internal or sensitive information.",
  "授权已被其他操作更新，本表单仍保留原修订。请重新载入并核对，不能覆盖最新授权。": "Entitlements changed elsewhere. This form still uses the old revision. Reload and review the latest version; do not overwrite it.",
  "本次未完成开通；已核实的线下收款仍须保留，刷新复核后再办理。": "Activation did not complete. Keep the verified offline payment record, refresh, and review before proceeding.",
