  "取消关联申请": "Unlink request",
  "所选申请已不再待处理，请取消关联并查看最新记录": "This request is no longer pending. Unlink it and review the latest record.",
  "额外功能授权": "Additional feature access",
  "仅可对已上线 / 受控试点功能向当前租户授权，不要求整体升级，不改变期限。公共下放在功能目录中维护；撤销须记录原因并保护既有业务。": "Grant access only to released or controlled-pilot features for this tenant. No full-plan upgrade is required, and the term stays unchanged. Manage Basic-wide availability in the feature catalog. Revocations require a reason and must protect existing operations.",
  "申请与线下收款记录": "Requests & offline payments",
  "订阅变更记录": "Subscription history",
  "暂无变更记录": "No changes yet",
  "申请详情与处理过程": "Request details & history",
  "处理结果已保存": "Outcome saved",
  "处理原因对租户可见；登记咨询或不续费不改变当前已付费期限，不自动获得基础版授权。": "These notes are visible to the tenant. Recording an inquiry or non-renewal does not change the paid term or automatically grant Basic access.",
  "可公开原因": "Notes visible to tenant",
  "统一截止": "Service end date",
  "详情 / 办理": "Details / manage",
  "直接为租户开通": "Activate for tenant",
  "到期范围": "Expiry",
