  "30 天内到期": "Expires within 30 days",
  "搜索租户订阅": "Search subscriptions",
  "搜索租户名称 / 编码": "Search tenant name or code",
  "租户订阅列表加载失败": "Could not load subscriptions",
  "选择要办理的租户": "Select a tenant",
  "进入详情 / 办理": "View / manage",
  "租户加载失败": "Could not load tenants",
  "搜索租户名称 / 编码（含尚未配置订阅的租户）": "Search tenant name or code (including tenants without a subscription)",
  "已保存标准价": "Standard price saved",
  "设置标准年费": "Set annual price",
  "未发布时不展示金额（显示「价格待公布」），不落 0 或虚构价；发布后才对租户显示标准年费。": "Unpublished prices display as 'Price pending', not zero or an estimated amount. The standard annual price becomes visible to tenants only after publication.",
  "已发布正式价格": "Published price",
  "标准年费（不填=待公布，不落 0）": "Annual price (blank = pending)",
  "新的价格方案版本": "New rate plan version",
  "留空自动生成新版本": "Leave blank to generate a version",
  "当前归属": "Current plan",
  "（已下放）": "(included in Basic)",
  "标准套餐价": "Standard plan price",
  "标准价加载失败": "Could not load standard prices",
  "价格待公布": "Price pending",
  "功能目录": "Feature catalog",
  "新增功能": "Add feature",
  "功能目录加载失败": "Could not load features",
  "未能刷新订阅期限，请重试；当前服务状态以服务器校验为准。": "Could not refresh the term. Try again. The server determines the current service status.",
  "关闭提醒": "Dismiss",
  "请联系租户管理员处理续费": "Ask your tenant admin to renew",
  "暂无该类功能": "No features in this category",
  "返回版本与订阅": "Back to plans",
  "订阅介绍加载失败": "Could not load plan information",
  "正式 PRO 销售尚未开放；四品类首批专业包及销售清单全部通过后才可正式收费。目前仅接受升级咨询或有明确范围的受控试点，不自动收款或开通。": "PRO sales are not open. Charging requires all four initial category packages and the sales checklist to pass review. For now, only upgrade inquiries or explicitly scoped controlled pilots are accepted. Payment and activation are not automatic.",
  "适用场景与范围": "Scope & use cases",
  "基础版保留已承诺的基础租赁经营闭环。PRO 规划面向项目协同、专业交接与养护等更复杂的经营需求，以下以实际发布目录为准；已有授权不重复作为升级卖点。": "Basic retains its promised core rental workflow. PRO is planned for more complex needs, including project coordination, specialist handovers and maintenance. Only the published catalog defines availability. Existing access is not a new upgrade benefit.",
  "全部适用品类": "All eligible categories",
  "查看某品类不表示已经营该品类；启用仍需相应空间、人员权限和业务准备。": "Viewing a category does not enable it. Activation still requires a workspace, staff permissions and operational readiness.",
  "标准年费与费用边界": "Annual price & extra costs",
  "有效基础版升级按相同计价口径核对剩余期间补差，保持统一截止。外部按量服务及硬件另计；不自动扣费、不默认试用。发布价格也不代表 PRO 销售条件已通过。": "Upgrading an active Basic plan uses the same pricing basis to calculate the remaining-term difference and keeps the end date. Usage-based services and hardware cost extra. There is no automatic charge or default trial. A published price does not mean PRO is approved for sale.",
  "常见问题": "FAQ",
  "升级不改变历史报价、订单及空间配置。到期停止新业务，既有履约、退款及结算保留；重新授权后仍须核验依赖，不自动发布旧配置。": "Upgrades do not change historical quotes, orders or workspace settings. Expiry blocks new business, but existing fulfillment, refunds and settlement remain available. Reauthorization still requires dependency checks and does not automatically publish old settings.",
  "请联系租户管理员办理咨询与续费。": "Contact your tenant admin for inquiries and renewal.",
  "仅待处理申请可撤销": "Only pending requests can be withdrawn",
  "申请已撤销": "Request withdrawn",
  "撤销失败，请联系平台": "Could not withdraw. Contact the platform.",
  "申请详情加载失败": "Could not load request details",
  "未找到当前租户的申请": "No request found for this tenant",
  "申请不等于开通；实际以平台核实到账并保存版本与期限为准，办理结果会显示真实生效时间。": "A request is not activation. Access takes effect only after the platform verifies payment and saves the plan and term. The outcome shows the actual effective time.",
  "申请与处理过程": "Request history",
  "确认撤销此待处理申请？": "Withdraw this pending request?",
  "已有线下资金请另联系平台处理，本操作不代表退款。": "Contact the platform separately about any offline payments. This action does not issue a refund.",
  "撤销申请": "Withdraw request",
  "申请编号": "Request no.",
