  "暂无处理过程记录": "No history yet",
  "申请已提交，实际以平台核实办理为准": "Request submitted. Activation requires platform confirmation.",
  "提交失败，请稍后重试或联系平台": "Could not submit. Try again later or contact the platform.",
  "提交申请": "Submit request",
  "申请不等于开通，也不会自动收款；外部费用可能另计。规划中 / 试点功能不计入本次交付承诺。": "A request does not activate access or collect payment. External costs may apply. Planned and pilot features are not part of this delivery commitment.",
  "希望使用的模块（按品类，可多选）": "Requested modules (select by category)",
  "仅表达意向，不保证规划项交付": "Interest only; planned features are not guaranteed",
